#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Global timer ID for simplicity
timer_t global_timerid;

// Signal handler function
static void handler(int sig, siginfo_t *si, void *uc) {
    printf("\n[Handler] Timer expired!\n");
}

int main() {
    // --- 1. Setup Signal Handling ---
    struct sigaction sa;
    sa.sa_flags = SA_SIGINFO;
    sa.sa_sigaction = handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGRTMIN, &sa, NULL) == -1) {
        perror("sigaction"); return 1;
    }

    // --- 2. Create the Timer ---
    struct sigevent sev;
    sev.sigev_notify = SIGEV_SIGNAL;
    sev.sigev_signo = SIGRTMIN;
    sev.sigev_value.sival_ptr = &global_timerid;

    if (timer_create(CLOCK_REALTIME, &sev, &global_timerid) == -1) {
        perror("timer_create"); return 1;
    }

    // --- 3. Define and Arm the Timer (Initial 3s, Repeat 1s) ---
    struct itimerspec new_value;
    new_value.it_value.tv_sec = 3;   
    new_value.it_value.tv_nsec = 0;
    new_value.it_interval.tv_sec = 1; 
    new_value.it_interval.tv_nsec = 0;

    printf("Arming timer: Initial 3s, Interval 1s.\n");
    if (timer_settime(global_timerid, 0, &new_value, NULL) == -1) {
        perror("timer_settime arm"); goto cleanup;
    }

    // --- 4. Fetch and Display Current State ---
    struct itimerspec current_value;
    if (timer_gettime(global_timerid, &current_value) == -1) {
        perror("timer_gettime"); goto cleanup;
    }
    printf("Current remaining time: %ld.%09lds\n",
           (long)current_value.it_value.tv_sec,
           (long)current_value.it_value.tv_nsec);

    // Wait for expirations
    printf("Waiting 4 seconds for signals...\n");
    sleep(4);

    // --- 5. Disarm the Timer ---
    new_value.it_value.tv_sec = 0;
    new_value.it_value.tv_nsec = 0;
    new_value.it_interval.tv_sec = 0;
    if (timer_settime(global_timerid, 0, &new_value, NULL) == -1) {
        perror("timer_settime disarm");
    }
    printf("Timer disarmed.\n");

cleanup:
    timer_delete(global_timerid);
    return 0;
}
